def build_graph(deps: Deps, checkpointer):
    # ------------------------------------------------------------------ helpers
    def status(run: RunState, st: str) -> None:
        run.status = st
        deps.store.set_status(run.run_id, st)

    def record(run: RunState, ctx: dict, action: dict | None = None, **patch) -> None:
        d = deps.store.get_decision(run.run_id, run.plan_version) or DecisionRecord(
            run_id=run.run_id, plan_version=run.plan_version,
            trigger_event_id=run.trigger_event.get("id", ""),
            model=ctx.get("model", "stub"), prompt_version=ctx.get("prompt_version", "v0"),
        ).model_dump(mode="json")
        if action:
            key = action["key"]
            d["actions"] = [a for a in d["actions"] if a.get("key") != key] + [action]
        d.update(patch)
        deps.store.save_decision(run.run_id, run.plan_version, d)
        ref = f"decision:{run.run_id}:{run.plan_version}"
        if ref not in run.audit_refs:
            run.audit_refs.append(ref)

    def do_gather(run: RunState) -> tuple[dict | None, str | None]:
        now = deps.clock()
        end = now + timedelta(hours=deps.horizon_hours)
        r, ag, vid = deps.reads, run.agency, run.vehicle_id
        with ThreadPoolExecutor(max_workers=4) as ex:
            f_v = ex.submit(r.get_vehicle, ag, vid)
            f_wo = ex.submit(r.find_open_work_order, ag, vid)
            f_b = ex.submit(r.list_affected_blocks, ag, vid, now, end)
            f_r = ex.submit(r.list_ready_vehicles, ag, now, end, Needs())
            res = {"vehicle": f_v.result(), "work_order": f_wo.result(), "blocks": f_b.result(),
                   "ready": f_r.result()}
            for name, x in res.items():
                if x.status != "ok":
                    return None, f"unavailable:{name}:{x.product or ''}:{x.note or x.status}"
            blocks: list[Block] = res["blocks"].value or []

def safe_evaluate(option: Option, facts: Facts, policy: AgencyPolicy, at: datetime) -> Clearance:
    """Fail closed: any exception inside clearance excludes the option and records why."""
    try:
        return evaluate_option(option, facts, policy, at)
    except Exception as e:  # noqa: BLE001
        return Clearance(items=[clearance_error("option", e)], excluded=True)


def noteworthy(i: ClearanceItem) -> bool:
    """Items worth showing a human: anything but a clean native pass."""
    return not (i.status == "pass" and i.basis == "native")


def summarise(items: list[ClearanceItem]) -> list[ClearanceItem]:
    """Merge per-block/per-operator repeats of the same verdict into one line each, keeping only items that
    are not a clean native pass (plan, decision record and panel show these)."""
    groups: dict[tuple, list[str]] = {}
    ack: dict[tuple, bool] = {}
    for i in items:
        if not noteworthy(i):
            continue
        k = (i.rule, i.status, i.basis)
        groups.setdefault(k, [])
        if i.detail and i.detail not in groups[k]:
            groups[k].append(i.detail)
        ack[k] = ack.get(k, False) or i.requires_ack
    return [ClearanceItem(rule=r, status=s, basis=b, detail="; ".join(d)[:600], requires_ack=ack[(r, s, b)])
            for (r, s, b), d in groups.items()]


def unacknowledged(items: list[ClearanceItem], acknowledged: list[str]) -> list[str]:
    """Rule ids with a requires_ack item the approver has not acknowledged."""
    return sorted({i.rule for i in items if i.requires_ack} - set(acknowledged))

def validate_output(raw: Any, facts: dict) -> tuple[ModelOutput | None, list[str]]:
    """Schema + feasibility. Returns (output, errors); output is None on schema failure."""
    try:
        out = ModelOutput.model_validate(raw)
    except ValidationError as e:
        return None, [f"schema:{e.error_count()} errors"]
    except Exception as e:  # noqa: BLE001
        return None, [f"schema:{e}"]
    errs: list[str] = []
    now, wend = _parse(facts["now"]), _parse(facts["window_end"])
    if out.decision == "monitor":
        return out, errs
    if out.decision == "pull_at_block_end" and out.pull_at is None:
        errs.append("pull_at_missing")
    pull_at = out.pull_at if out.pull_at is not None else now
    if pull_at.tzinfo is None and now.tzinfo is not None:
        errs.append("pull_at_naive_datetime")
        return out, errs
    if not (now <= pull_at <= wend):
        errs.append("pull_at_outside_window")
        return out, errs
    by_block = {b["block_id"]: b for b in facts["blocks"]}
    cctx = clearance_context(facts)
    seen_blocks: set[str] = set()
    used_s: set[str] = set()
    used_o: set[str] = set()
    for a in out.assignments:
        b = by_block.get(a.block_id)
        if b is None:
            errs.append(f"unknown_block:{a.block_id}")
            continue
        if a.block_id in seen_blocks:
            errs.append(f"duplicate_assignment:{a.block_id}")
        seen_blocks.add(a.block_id)
        if a.spare_id not in {s["id"] for s in b["spares"]}:
            errs.append(f"spare_not_feasible:{a.block_id}:{a.spare_id}")

